    CELL_SIGMA: 0.9,      // \uc140 \uc99d\uac70\uac00 \uac00\ub9ac\ud0a4\ub294 \uc5ed \uc8fc\ubcc0 \ud3ed(\uc5ed \ub2e8\uc704)
